import re, sys, unicodedata
inp, out = sys.argv[1], sys.argv[2]
def norm(s):
    s = unicodedata.normalize('NFC', s)
    for c in '“”″': s = s.replace(c, '"')
    for c in '‘’': s = s.replace(c, "'")
    s = re.sub(r'-\s*\d+\s*-', ' ', s)
    s = re.sub(r'\s+', ' ', s).strip()
    return s
def blocks(text):
    d = {}; cur=None; buf=[]
    for line in text.splitlines():
        m = re.match(r'^### (.+)$', line)
        if m:
            if cur: d[cur]='\n'.join(buf)
            cur=m.group(1).strip(); buf=[]
        elif cur: buf.append(line)
    if cur: d[cur]='\n'.join(buf)
    return d
I = blocks(open(inp,encoding='utf-8').read())
O = blocks(open(out,encoding='utf-8').read())
print('input blocks', len(I), 'output blocks', len(O))
print('missing', [k for k in I if k not in O]); print('extra', [k for k in O if k not in I])
bad=0; n=0; norms=0; rels=0
for k, body in O.items():
    src = norm(I.get(k,''))
    for line in body.splitlines():
        if line.startswith('원문:'): continue
        if re.match(r'^\s*규범:\s*규범:', line) or re.match(r'^\s+규범:', line): norms+=1
        if ' -' in line and '-> ' in line: rels+=1
        for ex in re.findall(r'"([^"]*)"', line):
            n+=1
            if norm(ex) not in src:
                bad+=1; print('FAIL', k, '|', ex)
        if line.count('"')%2: print('ODD QUOTES', k, line[:80])
print('excerpts', n, 'bad', bad, 'norms', norms, 'rels', rels)
